// Distribute engagement total across open billable tasks by Estimated Hours weight.
// Idempotent: sets Actual Hours to the recomputed share, never adds a delta.
const engagementHours = Number($('Recompute hours').item.json.actual_hours || 0);
const tasks = items.map(i => i.json);
const open = tasks.filter(t => {
  const status = t.property_status || t.Status || t.properties?.Status?.status?.name || t.properties?.Status?.select?.name;
  const billable = t.property_billable ?? t.properties?.Billable?.checkbox ?? true;
  return status !== 'done' && billable !== false;
});
const est = open.map(t => Number(t.properties?.['Estimated Hours']?.number || t['Estimated Hours'] || 1));
const estSum = est.reduce((a,b)=>a+b, 0) || open.length || 1;
return open.map((t, idx) => {
  const share = engagementHours * ((est[idx] || 1) / estSum);
  return {
    json: {
      page_id: t.id || t.page_id,
      actual_hours: Math.round(share * 100) / 100,
      stream_id: $('Recompute hours').item.json.stream_id,
    },
  };
});
